{
  "name": "@s-valent/opencode-goal",
  "version": "0.1.0",
  "description": "Persistent goals, automatic continuation, and shared TUI controls for OpenCode V2",
  "license": "MIT",
  "author": "s-valent",
  "keywords": ["opencode", "opencode-plugin", "goals"],
  "files": ["index.ts", "dist/", "src/", "README.md", "LICENSE"],
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./tui": "./dist/tui.js",
    "./rpc": "./src/rpc.ts"
  },
  "scripts": {
    "build": "bun run scripts/build.ts",
    "prepack": "npm run build",
    "check": "tsc --noEmit",
    "test": "bun test tests",
    "test:host": "bun run scripts/host-test.ts"
  },
  "dependencies": {
    "@opencode/client": "^2.1.3",
    "@opencode/plugin": "2.1.3",
    "zod": "^4.6.7"
  },
  "devDependencies": {
    "@types/bun": "^1.3.0",
    "@xterm/headless": "^6.0.0",
    "typescript": "^6.0.0"
  },
  "peerDependencies": {
    "@opentui/core": "^0.6.6",
    "@opentui/solid": "^0.6.6",
    "solid-js": "^1.9.12"
  }
}
